"use client";

import * as React from "react";
import { AnimatePresence, motion } from "motion/react";
import { Eye, EyeOff } from "lucide-react";
import { cn } from "@/lib/utils";

export interface WalletCardProps {
  /** Card number, any format — will be displayed as-is */
  cardNumber?: string;
  /** Cardholder name, revealed once the card is pulled out */
  cardHolder?: string;
  /** Expiry, revealed once the card is pulled out */
  expiry?: string;
  /** Brand label shown next to the logo */
  brand?: string;
  /** Label above the amount, e.g. "Limit Card" */
  limitLabel?: string;
  /** Amount string, e.g. "$43,865.00" */
  limitAmount?: string;
  /** Start pulled out */
  defaultOpen?: boolean;
  className?: string;
}

const MastercardMark = ({ className }: { className?: string }) => (
  <div className={cn("flex items-center", className)}>
    <span className="h-6 w-6 rounded-full bg-[#EB001B]" />
    <span className="-ml-2.5 h-6 w-6 rounded-full bg-[#F79E1B] mix-blend-screen" />
  </div>
);

const ChipGlyph = ({ className }: { className?: string }) => (
  <svg viewBox="0 0 32 24" fill="none" className={className}>
    <rect x="0.5" y="0.5" width="31" height="23" rx="4.5" fill="url(#wc-chip-grad)" stroke="rgba(0,0,0,0.25)" />
    <path d="M11 0.5V23.5M21 0.5V23.5M0.5 8H11M21 8H31.5M0.5 16H11M21 16H31.5M11 8H21V16H11V8Z" stroke="rgba(0,0,0,0.25)" strokeWidth="0.75" />
    <defs>
      <linearGradient id="wc-chip-grad" x1="0" y1="0" x2="32" y2="24" gradientUnits="userSpaceOnUse">
        <stop stopColor="#F4E7C1" />
        <stop offset="1" stopColor="#C9AC6A" />
      </linearGradient>
    </defs>
  </svg>
);

function WalletCard({
  cardNumber = "3745 6987 4096 3960",
  cardHolder = "Alex Morgan",
  expiry = "09/29",
  brand = "Master Card",
  limitLabel = "Limit Card",
  limitAmount = "$43,865.00",
  defaultOpen = false,
  className,
}: WalletCardProps) {
  const [open, setOpen] = React.useState(defaultOpen);
  const [visible, setVisible] = React.useState(true);

  const toggleOpen = React.useCallback(() => setOpen((v) => !v), []);

  return (
    <div
      className={cn(
        "relative mx-auto h-[340px] w-full max-w-[340px] select-none",
        className
      )}
    >
      <style>{`
        @keyframes wcSheen {
          0%   { background-position: 0% 30%; }
          50%  { background-position: 100% 70%; }
          100% { background-position: 0% 30%; }
        }
      `}</style>

      {/* Card — sits behind the pocket, slides out on click */}
      <motion.div
        className="absolute inset-x-6 top-0 z-10 origin-bottom cursor-pointer"
        role="button"
        tabIndex={0}
        aria-pressed={open}
        aria-label={open ? "Put card back in wallet" : "Pull card out of wallet"}
        onClick={toggleOpen}
        onKeyDown={(e) => {
          if (e.key === "Enter" || e.key === " ") {
            e.preventDefault();
            toggleOpen();
          }
        }}
        animate={{
          y: open ? -58 : 96,
          rotate: open ? -2.5 : 0,
          scale: open ? 1.04 : 1,
        }}
        whileTap={{ scale: open ? 1.01 : 0.98 }}
        transition={{ type: "spring", stiffness: 300, damping: 26, mass: 0.9 }}
      >
        <div
          className="relative aspect-[85.6/54] w-full overflow-hidden rounded-2xl ring-1 ring-white/10"
          style={{
            background:
              "linear-gradient(135deg, #4a4a4e 0%, #2b2b2e 45%, #161618 100%)",
            boxShadow: open
              ? "0 32px 55px -18px rgba(0,0,0,0.65)"
              : "0 10px 18px -10px rgba(0,0,0,0.55)",
          }}
        >
          <div
            className="pointer-events-none absolute inset-0 opacity-40 mix-blend-overlay"
            style={{
              backgroundImage:
                "linear-gradient(120deg, rgba(255,255,255,0.55) 0%, rgba(255,255,255,0) 35%, rgba(255,255,255,0) 100%)",
              backgroundSize: "220% 220%",
              animation: "wcSheen 16s ease-in-out infinite",
            }}
          />

          <div className="relative flex h-full flex-col justify-between p-4">
            <div className="flex items-start justify-between">
              <div className="flex items-center gap-2">
                <MastercardMark />
                <span className="text-sm font-semibold text-white/90">{brand}</span>
              </div>
              <span className="pt-1 text-right text-[13px] font-medium tracking-[0.12em] text-white/85">
                {cardNumber}
              </span>
            </div>

            <div className="flex items-end justify-between">
              <ChipGlyph className="h-6 w-8" />
              <AnimatePresence>
                {open && (
                  <motion.div
                    initial={{ opacity: 0, y: 6 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: 6 }}
                    transition={{ duration: 0.2, delay: open ? 0.15 : 0 }}
                    className="flex items-center gap-4 text-right"
                  >
                    <div>
                      <p className="text-[9px] uppercase tracking-wider text-white/40">Card holder</p>
                      <p className="text-xs font-medium text-white/85">{cardHolder}</p>
                    </div>
                    <div>
                      <p className="text-[9px] uppercase tracking-wider text-white/40">Expires</p>
                      <p className="text-xs font-medium text-white/85">{expiry}</p>
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          </div>
        </div>
      </motion.div>

      {/* Wallet pocket — drawn on top, notch lets the card peek through */}
      <div className="pointer-events-none absolute inset-x-0 bottom-0 z-20 h-[240px]">
        <svg
          viewBox="0 0 340 240"
          className="h-full w-full drop-shadow-[0_20px_35px_rgba(0,0,0,0.5)]"
          preserveAspectRatio="none"
        >
          <defs>
            <linearGradient id="wc-leather" x1="0" y1="0" x2="1" y2="1">
              <stop offset="0%" stopColor="#242427" />
              <stop offset="100%" stopColor="#101012" />
            </linearGradient>
          </defs>
          <path
            d="M28,0 L125,0 C125,38 145,44 170,44 C195,44 215,38 215,0 L312,0 A28,28 0 0 1 340,28 L340,212 A28,28 0 0 1 312,240 L28,240 A28,28 0 0 1 0,212 L0,28 A28,28 0 0 1 28,0 Z"
            fill="url(#wc-leather)"
          />
          <path
            d="M28,0 L125,0 C125,38 145,44 170,44 C195,44 215,38 215,0 L312,0 A28,28 0 0 1 340,28 L340,212 A28,28 0 0 1 312,240 L28,240 A28,28 0 0 1 0,212 L0,28 A28,28 0 0 1 28,0 Z"
            fill="none"
            stroke="rgba(255,255,255,0.18)"
            strokeWidth="1.5"
            strokeDasharray="4 5"
          />
          <circle cx="40" cy="38" r="5" fill="rgba(0,0,0,0.5)" stroke="rgba(255,255,255,0.14)" strokeWidth="1" />
          <circle cx="300" cy="38" r="5" fill="rgba(0,0,0,0.5)" stroke="rgba(255,255,255,0.14)" strokeWidth="1" />
        </svg>

        <div className="pointer-events-auto absolute inset-x-7 bottom-7 flex items-end justify-between">
          <div>
            <p className="text-xs font-medium text-white/40">{limitLabel}</p>
            <div className="mt-1 flex items-center gap-2">
              <p className="text-xl font-semibold tracking-tight text-white">
                {visible ? limitAmount : "••••••••"}
              </p>
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  setVisible((v) => !v);
                }}
                aria-label={visible ? "Hide amount" : "Show amount"}
                className="flex h-5 w-5 items-center justify-center rounded-full bg-white/10 text-white/60 transition hover:bg-white/20 hover:text-white"
              >
                {visible ? <Eye className="h-3 w-3" /> : <EyeOff className="h-3 w-3" />}
              </button>
            </div>
          </div>
          <span className="text-[11px] text-white/30">
            {open ? "tap to stow" : "tap to reveal"}
          </span>
        </div>
      </div>
    </div>
  );
}

WalletCard.displayName = "WalletCard";

export { WalletCard };
